func newSessionOptionValues(values []decodedOptionValue) SessionOptionValues {
	var result SessionOptionValues
	for _, value := range values {
		switch value.name {
		case "activity-action":
			result.activityAction = optionValueFromDecoded(ActivityAction(value.stringValue), value.origin)
		case "assume-paste-time":
			result.assumePasteTime = optionValueFromDecoded(value.int64Value, value.origin)
		case "base-index":
			result.baseIndex = optionValueFromDecoded(value.int64Value, value.origin)
		case "bell-action":
			result.bellAction = optionValueFromDecoded(BellAction(value.stringValue), value.origin)
		case "default-command":
			result.defaultCommand = optionValueFromDecoded(value.stringValue, value.origin)
		case "default-shell":
			result.defaultShell = optionValueFromDecoded(value.stringValue, value.origin)
		case "default-size":
			result.defaultSize = optionValueFromDecoded(value.stringValue, value.origin)
		case "destroy-unattached":
			result.destroyUnattached = optionValueFromDecoded(DestroyUnattached(value.stringValue), value.origin)
		case "detach-on-destroy":
			result.detachOnDestroy = optionValueFromDecoded(DetachOnDestroy(value.stringValue), value.origin)
		case "display-panes-active-colour":
			result.displayPanesActiveColour = optionValueFromDecoded(value.stringValue, value.origin)
		case "display-panes-colour":
			result.displayPanesColour = optionValueFromDecoded(value.stringValue, value.origin)
		case "display-panes-time":
			result.displayPanesTime = optionValueFromDecoded(value.int64Value, value.origin)
		case "display-time":
			result.displayTime = optionValueFromDecoded(value.int64Value, value.origin)
		case "focus-follows-mouse":
			result.focusFollowsMouse = optionValueFromDecoded(value.boolValue, value.origin)
		case "history-limit":
			result.historyLimit = optionValueFromDecoded(value.int64Value, value.origin)
		case "initial-repeat-time":
			result.initialRepeatTime = optionValueFromDecoded(value.int64Value, value.origin)
		case "key-table":
			result.keyTable = optionValueFromDecoded(value.stringValue, value.origin)
		case "lock-after-time":
			result.lockAfterTime = optionValueFromDecoded(value.int64Value, value.origin)
		case "lock-command":
			result.lockCommand = optionValueFromDecoded(value.stringValue, value.origin)
		case "message-command-style":
			result.messageCommandStyle = optionValueFromDecoded(value.stringValue, value.origin)
		case "message-format":
			result.messageFormat = optionValueFromDecoded(value.stringValue, value.origin)
		case "message-line":
			result.messageLine = optionValueFromDecoded(MessageLine(value.stringValue), value.origin)
		case "message-style":
			result.messageStyle = optionValueFromDecoded(value.stringValue, value.origin)
		case "mouse":
			result.mouse = optionValueFromDecoded(value.boolValue, value.origin)
		case "prefix":
			result.prefix = optionValueFromDecoded(value.stringValue, value.origin)
		case "prefix2":
			result.prefix2 = optionValueFromDecoded(value.stringValue, value.origin)
		case "prompt-command-cursor-style":
			result.promptCommandCursorStyle = optionValueFromDecoded(PromptCommandCursorStyle(value.stringValue), value.origin)
		case "prompt-cursor-colour":
			result.promptCursorColour = optionValueFromDecoded(value.stringValue, value.origin)
		case "prompt-cursor-style":
			result.promptCursorStyle = optionValueFromDecoded(PromptCursorStyle(value.stringValue), value.origin)
		case "renumber-windows":
			result.renumberWindows = optionValueFromDecoded(value.boolValue, value.origin)
		case "repeat-time":
			result.repeatTime = optionValueFromDecoded(value.int64Value, value.origin)
		case "set-titles":
			result.setTitles = optionValueFromDecoded(value.boolValue, value.origin)
		case "set-titles-string":
			result.setTitlesString = optionValueFromDecoded(value.stringValue, value.origin)
		case "silence-action":
			result.silenceAction = optionValueFromDecoded(SilenceAction(value.stringValue), value.origin)
		case "status":
			result.status = optionValueFromDecoded(Status(value.stringValue), value.origin)
		case "status-bg":
			result.statusBG = optionValueFromDecoded(value.stringValue, value.origin)
		case "status-fg":
			result.statusFG = optionValueFromDecoded(value.stringValue, value.origin)
		case "status-format":
			result.statusFormat = optionValueFromDecoded(value.sparseStringValue, value.origin)
		case "status-interval":
			result.statusInterval = optionValueFromDecoded(value.int64Value, value.origin)
		case "status-justify":
			result.statusJustify = optionValueFromDecoded(StatusJustify(value.stringValue), value.origin)
		case "status-keys":
			result.statusKeys = optionValueFromDecoded(StatusKeys(value.stringValue), value.origin)
		case "status-left":
			result.statusLeft = optionValueFromDecoded(value.stringValue, value.origin)
		case "status-left-length":
			result.statusLeftLength = optionValueFromDecoded(value.int64Value, value.origin)
		case "status-left-style":
			result.statusLeftStyle = optionValueFromDecoded(value.stringValue, value.origin)
		case "status-position":
			result.statusPosition = optionValueFromDecoded(StatusPosition(value.stringValue), value.origin)
		case "status-right":
			result.statusRight = optionValueFromDecoded(value.stringValue, value.origin)
		case "status-right-length":
			result.statusRightLength = optionValueFromDecoded(value.int64Value, value.origin)
		case "status-right-style":
			result.statusRightStyle = optionValueFromDecoded(value.stringValue, value.origin)
		case "status-style":
			result.statusStyle = optionValueFromDecoded(value.stringValue, value.origin)
		case "update-environment":
			result.updateEnvironment = optionValueFromDecoded(value.sparseStringValue, value.origin)
		case "visual-activity":
			result.visualActivity = optionValueFromDecoded(VisualActivity(value.stringValue), value.origin)
		case "visual-bell":
			result.visualBell = optionValueFromDecoded(VisualBell(value.stringValue), value.origin)
		case "visual-silence":
			result.visualSilence = optionValueFromDecoded(VisualSilence(value.stringValue), value.origin)
		case "word-separators":
			result.wordSeparators = optionValueFromDecoded(value.stringValue, value.origin)
		}
	}
	return result
}

