// PaneOptionValues is an immutable point-in-time view of known pane option values. Its zero value
// has no present values. Obtain it with [Pane.Options]; it may become stale after tmux changes.
// Use [OptionValue.Get] to read a present value and [OptionValue.Origin] to distinguish
// values set at this scope from inherited values.
type PaneOptionValues struct {
	allowPassthrough       OptionValue[AllowPassthrough]
	allowRename            OptionValue[bool]
	allowSetTitle          OptionValue[bool]
	alternateScreen        OptionValue[bool]
	copyModePositionFormat OptionValue[string]
	cursorColour           OptionValue[string]
	cursorStyle            OptionValue[CursorStyle]
	paneActiveBorderStyle  OptionValue[string]
	paneBorderFormat       OptionValue[string]
	paneBorderStyle        OptionValue[string]
	paneColours            OptionValue[SparseArray[string]]
	paneScrollbarsStyle    OptionValue[string]
	remainOnExit           OptionValue[RemainOnExit]
	remainOnExitFormat     OptionValue[string]
	scrollOnClear          OptionValue[bool]
	synchronizePanes       OptionValue[bool]
	treeModePreviewFormat  OptionValue[string]
	windowActiveStyle      OptionValue[string]
	windowStyle            OptionValue[string]
}

